; pins.asm -- chapter 35: register 15, bit by bit
; generated by gen35.py
        INCLUDE "msx.inc"
        OUTPUT "pins.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
ticks   EQU VARS                ; frames counted by isr
port1   EQU VARS + 1            ; register 14 of port 1
port2   EQU VARS + 2            ; and of port 2
r15     EQU VARS + 3            ; register 15, read back
r7      EQU VARS + 4            ; register 7, read back
way1    EQU VARS + 5            ; the directions
way2    EQU VARS + 6
bios    EQU VARS + 8            ; gtstck.asm: GTSTCK 1 and 2, GTTRIG 1 to 4
iff     EQU VARS + 14           ; gtstck.asm: 4 if the interrupts are on
pins    EQU VARS + 16           ; pins.asm: register 14 after each write
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; Register 15 written 14 ways in a row, and register 14 read after each:
; which of 15's bits joystick port 1 feels. Then 15 back as the BIOS left it.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; the display on, and the frame's signal
        in a, (VDP_CTRL)
main:   ei
        halt                    ; wait for the frame
        di                      ; the interrupts off: the PSG, then the VDP
        ld hl, values
        ld de, pins
        ld b, 14
value:  ld a, 15
        out (PSG_ADDR), a
        ld a, (hl)
written: out (PSG_WRITE), a     ; register 15, one of the values
        ld a, 14
        out (PSG_ADDR), a
        in a, (PSG_READ)        ; register 14
        ld (de), a
        inc hl
        inc de
        djnz value
        ld a, 15                ; register 15 back as the BIOS left it
        out (PSG_ADDR), a
        ld a, $8F
        out (PSG_WRITE), a
read:   ld hl, pins
        ld d, 3
.row:   ld e, 6
        push hl
        call at
        pop hl
        ld a, (hl)
        call hex
        inc hl
        inc d
        ld a, d
        cp 17
        jr nz, .row
        jp main

; isr: every frame, a frame counted. Keeps AF
isr:    push af
        in a, (VDP_CTRL)        ; the status: the signal down
        ld a, (ticks)
        inc a
        ld (ticks), a
        pop af
        ei
        ret

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
